'use strict';

/**
 * v1.44 QA — drift guard for docs/ROUTE-MAP.md, the navigational manifest of
 * the modular HTTP surface (generated by scripts/gen-route-map.js from the
 * live source). Same "generated artifact must match the code" discipline as
 * smoke-pzn-spec: if a route is added/moved/renamed and the map isn't
 * regenerated, the manifest silently lies about where routes live — fail the
 * build so it can't. No DB, no server: pure source parse.
 */

const fs = require('fs');
const path = require('path');
const { buildRouteMap } = require('./gen-route-map');

let fail = false;
function check(name, cond) {
  console.log((cond ? 'OK  ' : 'FAIL') + ' ' + name);
  if (!cond) fail = true;
}

const { markdown, total, fileCount } = buildRouteMap();
const mapPath = path.join(__dirname, '..', 'docs', 'ROUTE-MAP.md');

check('docs/ROUTE-MAP.md exists (the navigational manifest)', fs.existsSync(mapPath));
const committed = fs.existsSync(mapPath) ? fs.readFileSync(mapPath, 'utf8') : '';

check('the map covers a real, non-trivial route surface', total > 100 && fileCount > 20);
check('docs/ROUTE-MAP.md is IN SYNC with the source (regenerate with `npm run gen:route-map` if this fails)',
  committed === markdown);

// sanity: a few known routes must resolve to their owning module in the map
const owns = (route, file) => new RegExp('\\| `' + route.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '` \\| \\w+ \\| `' + file + '`').test(committed);
check('a moved admin route resolves to its module (/admin/inbox → routes/inbox.js)', owns('/admin/inbox', 'src/routes/inbox.js'));
check('a public route resolves to its module (/sitemap.xml → routes/seo-files.js)', owns('/sitemap.xml', 'src/routes/seo-files.js'));
check('an agent route resolves to its module (/agent/v1/ping → routes/agent-bridge.js)', owns('/agent/v1/ping', 'src/routes/agent-bridge.js'));

console.log('');
console.log(fail ? 'SMOKE ROUTE-MAP: FAIL' : 'SMOKE ROUTE-MAP: PASS');
process.exit(fail ? 1 : 0);
